return ['messages'=>['61003599af1219f1f1cdcced340617f8'=>'Una delegació de la Unió Europea visita l’<a href="https://www.irsjd.org/ca/">Institut de Recerca Sant Joan de Déu</a> per conèixer els projectes impulsats amb fons europeus','683d8024025a6a626bee02c07fe093ce'=>'Durant la trobada, l’equip de recerca va presentar iniciatives com <strong>GenomicScientia</strong>, centre pioner en medicina genòmica per a malalties minoritàries; <strong>ÚNICAS</strong>, una xarxa estatal que promou la medicina personalitzada en malalties rares pediàtriques; i diversos assaigs clínics en <strong>malalties neurometabòliques i leucèmies infantils</strong>.','753774d9023b43253dea68673a4087b8'=>'L’Institut de Recerca Sant Joan de Déu (IRSJD) ha rebut la visita d’una delegació de la Unió Europea, de la Secretaria General de Fons Europeus i de representants dels ministeris d’Hisenda, Sanitat i Presidència, així com de la Generalitat de Catalunya. Aquesta trobada ha permès compartir de primera mà com els fons FEDER i el Mecanisme de Recuperació i Resiliència (Next Generation EU) estan transformant la <strong>recerca pediàtrica</strong> a l’<a href="https://www.sjdhospitalbarcelona.org/ca">Hospital Sant Joan de Déu Barcelona</a>.','Durante la visita, el equipo de investigación presentó iniciativas como <strong>GenomicScientia</strong>, centro pionero en medicina genómica para enfermedades minoritarias; <strong>ÚNICAS</strong>, una red estatal que impulsa la medicina personalizada en enfermedades raras pediátricas; y diversos <strong>ensayos clínicos</strong> en enfermedades neurometabólicas y leucemias infantiles.'=>'Durant la trobada, l’equip de recerca va presentar iniciatives com <strong>GenomicScientia</strong>, centre pioner en medicina genòmica per a malalties minoritàries; <strong>ÚNICAS</strong>, una xarxa estatal que promou la medicina personalitzada en malalties rares pediàtriques; i diversos assaigs clínics en <strong>malalties neurometabòliques i leucèmies infantils</strong>.','El <a href="https://www.irsjd.org/es/">Institut de Recerca Sant Joan de Déu</a> (IRSJD) ha recibido la visita de una <strong>delegación de la Unión Europea</strong>, de la Secretaría General de Fondos Europeos y de representantes de los <strong>ministerios de Hacienda, Sanidad y Presidencia</strong>, así como de la <strong>Generalitat de Cataluña</strong>. Este encuentro ha permitido compartir de primera mano cómo los <strong>fondos FEDER</strong> y el <strong>Mecanismo de Recuperación y Resiliencia (Next Generation EU)</strong> están transformando la investigación pediátrica en el <a href="https://www.sjdhospitalbarcelona.org/es">Hospital Sant Joan de Déu Barcelona</a>.'=>'L’Institut de Recerca Sant Joan de Déu (IRSJD) ha rebut la visita d’una delegació de la Unió Europea, de la Secretaria General de Fons Europeus i de representants dels ministeris d’Hisenda, Sanitat i Presidència, així com de la Generalitat de Catalunya. Aquesta trobada ha permès compartir de primera mà com els fons FEDER i el Mecanisme de Recuperació i Resiliència (Next Generation EU) estan transformant la <strong>recerca pediàtrica</strong> a l’<a href="https://www.sjdhospitalbarcelona.org/ca">Hospital Sant Joan de Déu Barcelona</a>.','Estos proyectos ejemplifican cómo la inversión europea se traduce en <strong>conocimiento, innovación y nuevas oportunidades terapéuticas</strong>, mejorando la vida de los niños y sus familias.'=>'Aquests projectes exemplifiquen com la inversió europea es transforma en <strong>coneixement, innovació i noves oportunitats</strong> terapèutiques, millorant la vida dels infants i les seves famílies.','Sant Joan de Déu agradece la visita y el apoyo institucional que hacen posible un <strong>modelo de investigación de excelencia con impacto social</strong>.'=>'Sant Joan de Déu agraeix la visita i el suport institucional que fan possible un <strong>model de recerca d’excel·lència amb impacte social.</strong>','Una delegación de la Unión Europea visita el <a href="https://www.irsjd.org/ca/">Institut de Recerca Sant Joan de Déu</a> para conocer los proyectos impulsados con fondos europeos. '=>'Una delegació de la Unió Europea visita l’<a href="https://www.irsjd.org/ca/">Institut de Recerca Sant Joan de Déu</a> per conèixer els projectes impulsats amb fons europeus','b3607320e194e8d5d2a1e19dcdd94617'=>'Aquests projectes exemplifiquen com la inversió europea es transforma en <strong>coneixement, innovació i noves oportunitats</strong> terapèutiques, millorant la vida dels infants i les seves famílies.','c2acde6c41d165c707f1137b92da9da3'=>'Sant Joan de Déu agraeix la visita i el suport institucional que fan possible un <strong>model de recerca d’excel·lència amb impacte social.</strong>']];
